/* ── tiny shape renderer ─────────────────────────────────────────────── */
function Shape({ s, ...rest }) {
  if (s.t === "path")    return <path d={s.d} {...rest} />;
  if (s.t === "line")    return <line x1={s.x1} y1={s.y1} x2={s.x2} y2={s.y2} {...rest} />;
  if (s.t === "ellipse") return <ellipse cx={s.cx} cy={s.cy} rx={s.rx} ry={s.ry} {...rest} />;
  if (s.t === "circle")  return <circle cx={s.cx} cy={s.cy} r={s.r} {...rest} />;
  if (s.t === "poly")    return <polygon points={s.pts} {...rest} />;
  return null;
}
/* mirror a shape descriptor across the centre line */
function mirrorShape(s) {
  if (s.t === "line")    return { ...s, x1: mx(s.x1), x2: mx(s.x2) };
  if (s.t === "ellipse" || s.t === "circle") return { ...s, cx: mx(s.cx) };
  if (s.t === "poly")    return { ...s, pts: s.pts.split(" ").map(p => { const [a, b] = p.split(","); return `${mx(+a)},${b}`; }).join(" ") };
  if (s.t === "path")    return { ...s, d: s.d, _mirror: true }; // handled via transform group
  return s;
}

/* A group of side (mirrored) strokes + centre strokes, styled as a layer. */
function DetailGroup({ center = [], side = [], className }) {
  return (
    <g className={className}>
      {center.map((s, i) => <Shape key={"c" + i} s={tfShape(s)} />)}
      {side.map((s, i) => <Shape key={"r" + i} s={tfShape(s)} />)}
      <g transform={`matrix(-1 0 0 1 ${VB_W} 0)`}>
        {side.map((s, i) => <Shape key={"l" + i} s={tfShape(s)} />)}
      </g>
    </g>
  );
}

